"""
Process HWPX template: replace {{...}} placeholders with values from JSON.
Remove layout cache elements (<hp:linesegarray>) from modified paragraphs.
"""

import json
import re
import xml.etree.ElementTree as ET
from pathlib import Path
import shutil

# Read the replacement data
with open('/root/supplier_contact.json', 'r', encoding='utf-8') as f:
    replacements = json.load(f)

print("Replacements loaded:")
for k, v in replacements.items():
    print(f"  {{{{{k}}}}} -> {v}")

# Define namespace
NS_HP = "http://www.hancom.co.kr/hwpml/2010/HWPML"
namespaces = {'hp': NS_HP}

# Register namespace for proper serialization
ET.register_namespace('hp', NS_HP)

# Track which paragraphs were modified
modified_paras = set()

def replace_in_element(elem, replacements, modified_paras, ns_prefix='hp'):
    """Recursively replace placeholders in text and tail attributes."""
    # Check element text
    if elem.text:
        new_text = elem.text
        for key, value in replacements.items():
            placeholder = f'{{{{{key}}}}}'
            if placeholder in new_text:
                new_text = new_text.replace(placeholder, value)
                # Mark parent paragraph as modified
                parent = elem.getparent() if hasattr(elem, 'getparent') else None
                if parent is not None:
                    modified_paras.add(id(parent))
        if new_text != elem.text:
            elem.text = new_text
            # Find the containing paragraph
            current = elem
            while current is not None:
                if current.tag == f'{{{NS_HP}}}p':
                    modified_paras.add(id(current))
                    break
                current = current.getparent() if hasattr(current, 'getparent') else None

    # Check element tail
    if elem.tail:
        new_tail = elem.tail
        for key, value in replacements.items():
            placeholder = f'{{{{{key}}}}}'
            if placeholder in new_tail:
                new_tail = new_tail.replace(placeholder, value)
        if new_tail != elem.tail:
            elem.tail = new_tail

# Parse the XML file
xml_path = Path('/tmp/hwpx_work/template/Contents/section0.xml')
tree = ET.parse(xml_path)
root = tree.getroot()

# First pass: replace all placeholders
placeholder_pattern = re.compile(r'\{\{([^}]+)\}\}')

for elem in root.iter():
    # Replace in text content
    if elem.text:
        matches = placeholder_pattern.findall(elem.text)
        if matches:
            new_text = elem.text
            for key in matches:
                if key in replacements:
                    new_text = new_text.replace(f'{{{{{key}}}}}', replacements[key])
                else:
                    print(f"Warning: No replacement found for {{{{{key}}}}}")
            if new_text != elem.text:
                elem.text = new_text
                # Find containing paragraph
                parent = elem
                while parent is not None:
                    if parent.tag == f'{{{NS_HP}}}p':
                        modified_paras.add(id(parent))
                        break
                    parent = parent.find('..')  # Try to get parent

    # Replace in tail
    if elem.tail:
        matches = placeholder_pattern.findall(elem.tail)
        if matches:
            new_tail = elem.tail
            for key in matches:
                if key in replacements:
                    new_tail = new_tail.replace(f'{{{{{key}}}}}', replacements[key])
            elem.tail = new_tail

# Since ElementTree doesn't have getparent(), we need a different approach
# Let's do a second pass to find paragraphs with placeholders and remove linesegarray

# Re-parse with parent tracking
class ParentTracker:
    def __init__(self):
        self.parent_map = {}

    def build_parent_map(self, root):
        for parent in root.iter():
            for child in parent:
                self.parent_map[child] = parent
        return self.parent_map

tracker = ParentTracker()
parent_map = tracker.build_parent_map(root)

# Now find all elements with placeholders and track their parent paragraphs
paras_with_placeholders = set()

for elem in root.iter():
    if elem.text and '{{' in elem.text:
        # Walk up to find paragraph
        current = elem
        while current in parent_map:
            parent = parent_map[current]
            if parent.tag == f'{{{NS_HP}}}p':
                paras_with_placeholders.add(parent)
                break
            current = parent

print(f"\nFound {len(paras_with_placeholders)} paragraphs with placeholders")

# Remove linesegarray elements from those paragraphs
linesegarray_tag = f'{{{NS_HP}}}linesegarray'
removed_count = 0

for para in paras_with_placeholders:
    # Find and remove all linesegarray children
    children_to_remove = []
    for child in para:
        if child.tag == linesegarray_tag:
            children_to_remove.append(child)

    for child in children_to_remove:
        para.remove(child)
        removed_count += 1

print(f"Removed {removed_count} linesegarray elements")

# Verify no placeholders remain
xml_str = ET.tostring(root, encoding='unicode')
remaining_placeholders = re.findall(r'\{\{[^}]+\}\}', xml_str)
if remaining_placeholders:
    print(f"WARNING: Remaining placeholders: {remaining_placeholders}")
else:
    print("All placeholders replaced successfully!")

# Write back preserving XML declaration
tree.write(xml_path, encoding='UTF-8', xml_declaration=True)

print(f"\nProcessed: {xml_path}")
"}

